// ── Helpers ───────────────────────────────────────────────────
export function getProductsByCategory(categorySlug: string): Product[] {
  return products.filter((p) => p.categorySlug === categorySlug);
}

export function getProductBySlug(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug);
}

export function getProductByCategoryAndSlug(
  categorySlug: string,
  productSlug: string
): Product | undefined {
  return products.find(
    (p) => p.categorySlug === categorySlug && p.slug === productSlug
  );
}

export function getAllProductSlugs(): Array<{
  categorySlug: string;
  productSlug: string;
}> {
  return products.map((p) => ({
    categorySlug: p.categorySlug,
    productSlug: p.slug,
  }));
}

export function getFeaturedProducts(count: number = 6): Product[] {
  return products.slice(0, count);
}

export function getRelatedProducts(
  productSlug: string,
  categorySlug: string,
  count: number = 4
): Product[] {
  return products
    .filter((p) => p.categorySlug === categorySlug && p.slug !== productSlug)
    .slice(0, count);
}
